const state={ar:false,car:0,start:'2026-11-02T10:00',end:'2026-11-04T10:00',place:'airport',returnPlace:'airport',hotel:'',returnHotel:'',flight:'',name:'',phone:'',email:'',filter:'all',searched:false};
const cars=[{name:'Volkswagen T-Roc',image:'troc',rate:40000,kind:'SUV'},{name:'Volkswagen Golf 8',image:'golf8',rate:35000,kind:'Compacte'},{name:'Dacia Duster',image:'duster',rate:35000,kind:'SUV'}];
const t=(fr,ar)=>state.ar?ar:fr;
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat(state.ar?'ar-MA':'fr-FR',{maximumFractionDigits:0}).format(n/100)+' '+t('DH','درهم');
const days=()=>Math.max(1,Math.ceil((new Date(state.end)-new Date(state.start))/86400000));
const car=()=>cars[state.car];
const date=x=>new Intl.DateTimeFormat(state.ar?'ar-MA':'fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(x));
const place=x=>x==='airport'?t('Aéroport de Tanger','مطار طنجة'):t('Hôtel à Tanger','فندق بطنجة');
function go(page){history.pushState(null,'','#'+page);render();window.scrollTo(0,0)}
function field(label,key,type='text',required=true){return `<label>${label}<input name="${key}" type="${type}" value="${esc(state[key])}" ${required?'required':''} ${key==='phone'?'autocomplete="tel" inputmode="tel" pattern="[+0-9 ()-]{8,20}"':''} ${key==='name'?'autocomplete="name"':''} ${key==='email'?'autocomplete="email"':''}></label>`}
function placeField(label,key){return `<label>${label}<select name="${key}"><option value="airport" ${state[key]==='airport'?'selected':''}>${place('airport')}</option><option value="hotel" ${state[key]==='hotel'?'selected':''}>${place('hotel')}</option></select></label>`}
function search(){return `<form id="search" class="search"><div class="fields">${placeField(t('Lieu de livraison','مكان التسليم'),'place')}${field(t('Départ · date et heure','البداية · التاريخ والساعة'),'start','datetime-local')}${field(t('Retour · date et heure','الرجوع · التاريخ والساعة'),'end','datetime-local')}<button class="primary" type="submit">${t('Voir les voitures','شوف السيارات')} <span>↗</span></button></div><div class="mini" style="margin-top:12px">${t('Hôtel ou aéroport à Tanger. Frais de livraison à confirmer avec l’agence.','الفندق أو مطار طنجة. مصروف التوصيل كيتأكد مع الوكالة.')}</div><div class="error" role="alert" id="date-error"></div></form>`}
function totals(){return `<div class="line"><span>${t('Départ','البداية')}</span><b>${date(state.start)}</b></div><div class="line"><span>${t('Retour','الرجوع')}</span><b>${date(state.end)}</b></div><div class="line"><span>${money(car().rate)} × ${days()} ${t('jours','أيام')}</span><b>${money(car().rate*days())}</b></div><div class="line"><span>${t('Livraison','التسليم')}</span><span>${place(state.place)}</span></div><div class="line"><span>${t('Frais de livraison','مصروف التوصيل')}</span><span>${t('À confirmer','خاصو التأكيد')}</span></div><div class="line total"><span>${t('Total location','مجموع الكراء')}</span><span>${money(car().rate*days())}</span></div><div class="notice">${t('Caution séparée : 3 000 DH (exemple). Elle ne fait pas partie du prix de location.','الضمان منفصل: ٣٬٠٠٠ درهم (مثال). ما داخلش فثمن الكراء.')}</div><p class="mini">${t('Tarifs, équipements et conditions illustratifs pour cette maquette. Aucun paiement en ligne.','الأثمنة والتجهيزات والشروط توضيحية فهاد المعاينة. ما كاين حتى أداء عبر الموقع.')}</p>`}
function home(){const list=cars.map((c,i)=>({c,i})).filter(({c})=>state.filter==='all'||c.kind===state.filter);return `<div class="hero"><div><div class="eyebrow">BEN SBIH · TANGER</div><h1>${t('Tanger.<br>À votre <em>rythme.</em>','طنجة.<br>على <em>خاطرك.</em>')}</h1><p>${t('Les petites escapades. Les grandes découvertes. Trouvez la voiture qui accompagne votre séjour.','خرجة قصيرة ولا سفر طويل. لقا السيارة اللي تناسب إقامتك.')}</p><a class="primary" href="#fleet" data-fleet>${t('Découvrir les voitures','اكتشف السيارات')} ↗</a></div><div class="hero-visual"><img src="assets/troc.jpg" alt="Volkswagen T-Roc"><div class="visual-label"><div><b>Volkswagen T-Roc</b><br><span class="mini">${t('Votre prochaine escapade','رحلتك الجاية')}</span></div><span class="link">400 ${t('DH / jour','درهم / اليوم')}</span></div></div></div>${search()}<section class="section" id="fleet"><div class="section-head"><div><div class="eyebrow">${t('À CHACUN SA ROUTE','لكل واحد طريقو')}</div><h2>${state.searched?t('Vos voitures pour ces dates','السيارات لهاد المدة'):t('Choisissez votre prochaine aventure.','اختار رحلتك الجاية.')}</h2><p class="mini">${t('Sélection de démonstration · disponibilité simulée','اختيارات تجريبية · التوفر محاكاة')}</p></div><label>${t('Type de voiture','نوع السيارة')}<select id="filter"><option value="all">${t('Toutes les voitures','جميع السيارات')}</option><option value="SUV" ${state.filter==='SUV'?'selected':''}>SUV</option><option value="Compacte" ${state.filter==='Compacte'?'selected':''}>${t('Compacte','مدمجة')}</option><option value="electric" ${state.filter==='electric'?'selected':''}>${t('Électrique','كهربائية')}</option></select></label></div><div class="cars">${list.map(({c,i})=>`<article class="car"><a href="#detail" data-car="${i}"><img src="assets/${c.image}.jpg" alt="${c.name}" loading="lazy"></a><div class="car-body"><div class="eyebrow">${c.kind==='SUV'?'SUV':t('COMPACTE','مدمجة')}</div><h3>${c.name}</h3><p class="mini">${t('5 places · Climatisation · Exemple de véhicule','٥ بلايص · مكيف · سيارة توضيحية')}</p><div class="car-bottom"><span><b>${money(c.rate)}</b><span class="mini"> / ${t('jour','اليوم')}</span></span><a class="link" href="#detail" data-car="${i}">${t('Découvrir','التفاصيل')} ↗</a></div></div></article>`).join('')}</div>${!list.length?`<div class="empty"><h3>${t('Aucune voiture dans cette catégorie','ما كايناش سيارة بهاد النوع')}</h3><p>${t('Essayez une autre catégorie pour continuer votre recherche.','اختار نوع آخر باش تكمل البحث.')}</p><button class="secondary" id="reset-filter">${t('Afficher toutes les voitures','عرض جميع السيارات')}</button></div>`:''}</section><section class="services" id="delivery"><div><div class="eyebrow" style="color:#87aaff">${t('VOTRE ARRIVÉE, SIMPLIFIÉE','وصولك بسهولة')}</div><h2>${t('On se retrouve<br>où vous arrivez.','نتلاقاو فين<br>غادي توصل.')}</h2><p>${t('Choisissez votre lieu. L’agence vous recontacte pour organiser la remise des clés.','اختار المكان. الوكالة كتتواصل معاك باش تنظم تسليم المفاتيح.')}</p></div><div><div class="service"><strong>↗ ${t('À l’aéroport de Tanger','فمطار طنجة')}</strong><p>${t('Vous pouvez préciser votre vol pour faciliter le rendez-vous.','تقدر تزيد رقم الرحلة باش تسهل الموعد.')}</p></div><div class="service"><strong>⌂ ${t('À votre hôtel','فالفندق ديالك')}</strong><p>${t('Indiquez le nom de votre hôtel à Tanger dans la demande.','كتب سميت الفندق ديالك فطنجة ملي تدير الطلب.')}</p></div><small>${t('Lieu et éventuels frais à valider avec l’agence.','المكان والمصاريف المحتملة خاص تأكيدها مع الوكالة.')}</small></div></section><section class="section"><div class="eyebrow">${t('AVANT DE PRENDRE LA ROUTE','قبل ما تنطلق')}</div><h2>${t('Quelques réponses, simplement.','أجوبة بسيطة على أسئلتك.')}</h2><details><summary>${t('Ma demande confirme-t-elle ma réservation ?','واش الطلب كيأكد الحجز؟')}</summary><p>${t('Non. L’agence vérifie votre demande et vous contacte. La confirmation vient après accord et vérification du paiement.','لا. الوكالة كتراجع الطلب وكتتواصل معاك. التأكيد كيجي من بعد الاتفاق والتحقق من الأداء.')}</p></details><details><summary>${t('Dois-je payer sur le site ?','واش نخلص فالموقع؟')}</summary><p>${t('Aucun paiement en ligne. Les modalités sont convenues avec l’agence.','ما كاينش الأداء عبر الموقع. طريقة الأداء كتتفق عليها مع الوكالة.')}</p></details><details><summary>${t('Quelles sont les conditions de location ?','شنو شروط الكراء؟')}</summary><p>${t('Âge, permis, kilométrage, assurance et caution seront précisés après validation des conditions de l’agence.','العمر والرخصة والكيلومترات والتأمين والضمان غادي يتحددو من بعد تأكيد شروط الوكالة.')}</p></details></section>`}
function detail(){return `<a class="back" href="#home">← ${t('Toutes les voitures','جميع السيارات')}</a><div class="detail-grid"><div><div class="detail-title"><div class="eyebrow">${t('VOTRE VOITURE À TANGER','سيارتك فطنجة')}</div><h1>${car().name}</h1><p>${t('De la ville aux escapades, prenez votre temps.','فالمدينة ولا فالطريق، خذ راحتك.')}</p></div><img class="detail-photo" src="assets/${car().image}.jpg" alt="${car().name}"><div class="specs"><div class="spec">${t('5 places','٥ بلايص')}</div><div class="spec">${t('Climatisation','مكيف الهواء')}</div><div class="spec">${t('5 portes','٥ أبواب')}</div></div><p class="mini">${t('Photo de démonstration. Équipements à valider pour le véhicule proposé.','صورة تجريبية. التجهيزات خاصها تتأكد بالنسبة للسيارة المعروضة.')}</p><h3>${t('Un départ bien préparé.','انطلاقة منظمة.')}</h3><p>${t('Choisissez vos dates et votre lieu de livraison. Vos choix vous suivent jusqu’à la demande, sans les saisir à nouveau.','اختار التواريخ ومكان التسليم. اختياراتك كيبقاو محفوظين حتى للطلب بلا ما تعاود تعمرهم.')}</p><details><summary>${t('Kilométrage, assurance et conditions','الكيلومترات والتأمين والشروط')}</summary><p>${t('Ces conditions doivent encore être confirmées par l’agence avant publication. Aucun forfait ni couverture ne sont présumés dans cette maquette.','هاد الشروط خاص الوكالة تأكدها قبل النشر. هاد المعاينة ما كتفترض حتى سقف كيلومترات ولا تغطية تأمين.')}</p></details></div><aside class="panel summary"><span class="price">${money(car().rate)}</span> <span class="mini">/ ${t('jour','اليوم')}</span>${totals()}<button class="primary full" id="request">${t('Demander cette voiture','طلب هاد السيارة')} ↗</button><button class="full link" id="edit-dates">${t('Modifier mes dates ou mon lieu','تبديل التواريخ أو المكان')}</button></aside></div>`}
function request(){return `<a class="back" href="#detail">← ${t('Retour à la voiture','رجوع للسيارة')}</a><div class="steps">${t('01 · Votre voiture','٠١ · السيارة')} &nbsp; / &nbsp; <b>${t('02 · Votre demande','٠٢ · الطلب')}</b></div><h2>${t('Et si votre séjour commençait ici ?','رحلتك كتبدا من هنا.')}</h2><p>${t('Quelques informations pour organiser votre arrivée.','معلومات قليلة باش ننظمو وصولك.')}</p><div class="detail-grid request"><form id="request-form" class="panel"><div class="form-section"><h3>${t('1. Comment vous contacter ?','١. كيفاش نتواصلو معاك؟')}</h3><div class="form-grid">${field(t('Nom complet','الاسم الكامل'),'name')}${field(t('Téléphone avec indicatif','الهاتف مع رمز البلد'),'phone','tel')}<div class="wide">${field(t('E-mail · facultatif','البريد الإلكتروني · اختياري'),'email','email',false)}</div></div></div><div class="form-section"><h3>${t('2. Où vous retrouver ?','٢. فين نتلاقاو؟')}</h3><div class="form-grid">${placeField(t('Livraison','التسليم'),'place')}${state.place==='hotel'?field(t('Nom de l’hôtel à Tanger','سميت الفندق فطنجة'),'hotel'):field(t('Numéro de vol · facultatif','رقم الرحلة · اختياري'),'flight','text',false)}${placeField(t('Restitution','الاسترجاع'),'returnPlace')}${state.returnPlace==='hotel'?field(t('Hôtel de restitution','فندق الاسترجاع'),'returnHotel'):''}</div><p class="mini">${t('Les frais éventuels seront confirmés avant votre accord.','أي مصاريف إضافية غادي تتأكد قبل موافقتك.')}</p></div><div class="notice">${t('Vous envoyez une demande, pas une réservation confirmée. Aucun paiement ni document d’identité n’est demandé ici.','كتصيفط طلب، ماشي حجز مؤكد. ما مطلوب منك لا أداء لا وثيقة الهوية هنا.')}</div><p class="mini">${t('Prototype local : utilisez des coordonnées fictives. Rien n’est envoyé à l’agence.','معاينة محلية: استعمل معلومات وهمية. ما كيتصيفط والو للوكالة.')}</p><button class="primary full" type="submit">${t('Simuler l’envoi de ma demande','محاكاة إرسال الطلب')} ↗</button></form><aside class="panel summary"><div class="eyebrow">${t('VOTRE SÉJOUR','رحلتك')}</div><h3>${car().name}</h3>${totals()}<a class="link" href="#detail">${t('Revoir la voiture','راجع السيارة')}</a></aside></div>`}
function success(){return `<section class="success"><div class="check">✓</div><div class="eyebrow">${t('SIMULATION RÉUSSIE · DEMO-WEB-001','نجحات المحاكاة · DEMO-WEB-001')}</div><h2>${t('Votre demande est prête.','الطلب ديالك واجد.')}</h2><p>${t('Dans le site final, l’agence recevra ces informations et vous contactera pour vérifier les disponibilités et les modalités.','فالموقع النهائي، الوكالة غادي تتوصل بهاد المعلومات وتتواصل معاك باش تراجع التوفر والتفاصيل.')}</p><div class="panel" style="text-align:start"><h3>${car().name}</h3>${totals()}<div class="line"><span>${t('Contact','التواصل')}</span><b>${esc(state.name)}</b></div><div class="line"><span>${t('Téléphone','الهاتف')}</span><b dir="ltr">${esc(state.phone)}</b></div><div class="line"><span>${t('Restitution','الاسترجاع')}</span><b>${place(state.returnPlace)}</b></div>${state.place==='hotel'?`<div class="line"><span>${t('Hôtel','الفندق')}</span><b>${esc(state.hotel)}</b></div>`:''}</div><p class="mini">${t('Aucune demande réelle créée. Aucune voiture bloquée.','ما تسجل حتى طلب حقيقي وما تبلوكت حتى سيارة.')}</p><button class="primary" id="home">${t('Retour à l’accueil','رجوع للرئيسية')}</button></section>`}
function render(){const page=location.hash.slice(1)||'home';document.documentElement.lang=state.ar?'ar':'fr';document.documentElement.dir=state.ar?'rtl':'ltr';document.getElementById('app').innerHTML=`<div class="demo">${t('MAQUETTE INTERACTIVE · Prix et disponibilités illustratifs · Aucun envoi réel','معاينة تفاعلية · الأثمنة والتوفر توضيحيين · بلا إرسال حقيقي')}</div><header><a href="#home" aria-label="${t('Accueil BEN SBIH','الرئيسية')} "><img src="assets/logo.svg" alt="BEN SBIH RENTAL CAR"></a><nav><a href="#fleet" data-fleet class="nav-extra">${t('Nos voitures','السيارات')}</a><a href="#delivery" data-delivery class="nav-extra">${t('Livraison','التوصيل')}</a><button id="language">${state.ar?'FR':'العربية'}</button></nav></header><main class="wrap">${page==='detail'?detail():page==='request'?request():page==='success'?success():home()}</main><footer><b>BEN SBIH RENTAL CAR · TANGER</b><span>${t('Maquette de parcours · Conditions commerciales à valider','معاينة المسار · الشروط التجارية خاصها التأكيد')}</span></footer>`;bind()}
function bind(){document.getElementById('language').onclick=()=>{state.ar=!state.ar;render()};document.querySelectorAll('[data-car]').forEach(a=>a.onclick=e=>{e.preventDefault();if(!state.start||!state.end||new Date(state.end)<=new Date(state.start)){document.getElementById('date-error').textContent=t('Choisissez des dates valides avant de continuer.','اختار تواريخ صحيحة باش تكمل.');document.getElementById('search').scrollIntoView();return}state.car=Number(a.dataset.car);go('detail')});document.querySelectorAll('[data-fleet]').forEach(a=>a.onclick=e=>{e.preventDefault();go('home');document.getElementById('fleet').scrollIntoView()});document.querySelectorAll('[data-delivery]').forEach(a=>a.onclick=e=>{e.preventDefault();go('home');document.getElementById('delivery').scrollIntoView()});document.querySelectorAll('input,select[name]').forEach(el=>{el.addEventListener('input',()=>{state[el.name]=el.value});if(el.tagName==='SELECT')el.addEventListener('change',()=>{state[el.name]=el.value;if(location.hash==='#request')render()})});const s=document.getElementById('search');if(s)s.onsubmit=e=>{e.preventDefault();if(new Date(state.end)<=new Date(state.start)){document.getElementById('date-error').textContent=t('Le retour doit être après le départ.','الرجوع خاصو يكون من بعد البداية.');return}state.searched=true;render();document.getElementById('fleet').scrollIntoView()};const f=document.getElementById('filter');if(f)f.onchange=()=>{state.filter=f.value;render();document.getElementById('fleet').scrollIntoView()};const reset=document.getElementById('reset-filter');if(reset)reset.onclick=()=>{state.filter='all';render();document.getElementById('fleet').scrollIntoView()};const r=document.getElementById('request');if(r)r.onclick=()=>go('request');const ed=document.getElementById('edit-dates');if(ed)ed.onclick=()=>{go('home');document.getElementById('search').scrollIntoView();document.querySelector('[name=start]').focus()};const form=document.getElementById('request-form');if(form)form.onsubmit=e=>{e.preventDefault();if(!state.name.trim()||(state.place==='hotel'&&!state.hotel.trim())||(state.returnPlace==='hotel'&&!state.returnHotel.trim()))return;go('success')};const h=document.getElementById('home');if(h)h.onclick=()=>go('home')}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
